const p = $input.first().json.body ?? $input.first().json;
if (!p || typeof p !== 'object') throw new Error('Invalid request body');
if (typeof p.idempotencyKey !== 'string' || !/^[a-z][a-z0-9-]{2,40}:[A-Za-z0-9:._-]{6,160}$/.test(p.idempotencyKey)) throw new Error('Invalid idempotency key');
if (typeof p.notificationType !== 'string' || !/^[a-z0-9_]{3,60}$/.test(p.notificationType)) throw new Error('Invalid notification type');
const isEmail = v => typeof v === 'string' && v.length <= 254 && /^[^\s@,;<>]+@[^\s@,;<>]+\.[^\s@,;<>]+$/.test(v);
if (!Array.isArray(p.recipients) || p.recipients.length < 1 || p.recipients.length > 20 || !p.recipients.every(isEmail)) throw new Error('Invalid recipient list');
if (typeof p.subject !== 'string' || !p.subject.trim() || p.subject.length > 300 || /[\r\n]/.test(p.subject)) throw new Error('Invalid subject');
if (typeof p.html !== 'string' || !p.html.length || p.html.length > 200000) throw new Error('Invalid HTML');
if (p.replyTo != null && p.replyTo !== '' && !isEmail(p.replyTo)) throw new Error('Invalid replyTo');
const b = p.emailBranding;
if (!b || typeof b.fromName !== 'string' || !b.fromName.trim() || b.fromName.length > 100 || /[\r\n<>"]/.test(b.fromName) || !isEmail(b.fromEmail)) throw new Error('Invalid sender');
// Sender allowlist: only the verified Lepefy sending domain.
if (!/@lepefy\.com$/i.test(b.fromEmail)) throw new Error('Sender not allowed');
// Optional file attachments: at most 5, known document types, ~10 MB of base64 in total.
const TYPES = { pdf: 'application/pdf', csv: 'text/csv', xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg' };
const attachments = p.attachments == null ? [] : p.attachments;
if (!Array.isArray(attachments) || attachments.length > 5) throw new Error('Invalid attachments');
let total = 0;
for (const a of attachments) {
  const ext = typeof a?.filename === 'string' ? (a.filename.match(/\.([a-z0-9]+)$/i) || [])[1]?.toLowerCase() : null;
  if (!ext || !TYPES[ext] || !/^[A-Za-z0-9][A-Za-z0-9 ._()-]{0,119}$/.test(a.filename)) throw new Error('Invalid attachment name');
  if (typeof a.contentType !== 'string' || a.contentType.split(';')[0].trim().toLowerCase() !== TYPES[ext]) throw new Error('Invalid attachment type');
  if (typeof a.contentBase64 !== 'string' || !a.contentBase64.length || !/^[A-Za-z0-9+/]+={0,2}$/.test(a.contentBase64)) throw new Error('Invalid attachment content');
  total += a.contentBase64.length;
}
if (total > 14000000) throw new Error('Attachments too large');
return [{json:{idempotencyKey:p.idempotencyKey,notificationType:p.notificationType,tenantId:p.tenantId ?? null,recipients:p.recipients,subject:p.subject,html:p.html,replyTo:p.replyTo || '',fromName:b.fromName.trim(),fromEmail:b.fromEmail,attachments:attachments.map(a => ({filename:a.filename,contentType:a.contentType,contentBase64:a.contentBase64}))}}];

// Turns the validated attachments into binary properties for the SMTP node.
const attachments = $('Validate payload').first().json.attachments || [];
const binary = {};
attachments.forEach((a, i) => {
  binary[`attachment_${i}`] = { data: a.contentBase64, mimeType: a.contentType, fileName: a.filename };
});
return [{ json: { attachmentCount: attachments.length }, binary }];
